-- Room Service menu. Run once in the Supabase SQL editor AFTER schema.sql + seed.sql.
-- Adds rows only (no structure changes). Safe to re-run: existing rows are left untouched.

-- 1) Room Service sections and items that exist only on the room service menu


-- 2) Tag Encima dishes that are also on the room service menu (they then show in both tabs)
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'especiales' and name in ('Pan-Seared Salmon', 'Grilled Porkchop') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'pasta' and name in ('Shrimp Scampi', 'Beef Lasagna', 'Grilled Chicken Pesto', 'Truffle Mushroom') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'pizza' and name in ('Suprema', 'Cheeseburger Pizza', 'Texmex BBQ', 'Pepperoni', 'Hawaiian Bacon', 'The White House', 'Margherita') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'tacos' and name in ('Club Sandwich', 'Shrimp Quesadilla', 'Beef Quesadilla', 'Chicken Quesadilla', 'Grilled Cheese Sandwich') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'naked-burrito' and name in ('Beef Naked Burrito', 'Chicken Naked Burrito', 'Shrimp Naked Burrito') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'sides' and name in ('Truffle French Fries', 'Mexican Fried Rice', 'Flour Tortilla', 'Buttered Corn and Carrots', 'Garlic Fried Rice', 'Plain Rice') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'dessert' and name in ('Burnt Basque Cheesecake', 'Strawberry Panna Cotta', 'Pistachio Tres Leches Cake') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'coffee' and name in ('Caramel Macchiato') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'tea' and name in ('Earl Grey', 'English Breakfast') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'refreshers' and name in ('Mango Shake', 'Watermelon Shake', 'Encima Iced Tea') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'wines-red' and name in ('Suntana Cabernet Sauvignon') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'wines-white' and name in ('Casa Defrà Chardonnay') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'beer' and name in ('Tanduay Ice Vodka Lemonade', 'San Miguel Light', 'San Miguel Pale Pilsen', 'Smirnoff Mule') and not ('roomservice' = any(tags));
update public.items set tags = array_append(tags, 'roomservice') where section_id = 'soda' and name in ('Evian Still Water', 'Ginger Ale', 'Coke Regular', 'Royal') and not ('roomservice' = any(tags));
